using Solution.Parser.CSharp;

namespace AspNetCore.MinimalApi.Sdk.CodeRules
{
    [TestCategory("Coding-Rules")]
    [TestCategory("API - Controllers")]
    [TestClass]
    public class RJIT_CR_API_C_00029 : ControllerTestBase
    {
        [TestMethod]
        public void Should_Only_Have_Only_Mediator_Call_Statement()
        {
            var moreAsMediatorUsage = (from controller in Controllers
                                       where controller.Constructors.Any(c => c.Parameters.Any(p => p.Type == "IMediator"))
                                       from method in controller.Methods
                                       where method.LineStatements.Any() && method.LineStatements.Count > 2
                                       select new
                                       {
                                           Error = $@"
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Controller: {controller.FullQualifiedName}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Method:     

{method.MethodValue.FormatSyntaxTree()}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Sample:     

{method.ReturnParameter} {method.Name}({method.Parameters.Select(p => $"{p.Type} {p.Name}").Flatten(", ")})
{{               
    return _mediator.SendAsync(new GetData());
}}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
"
                                       }).ToImmutableList();

            Assert.IsTrue(moreAsMediatorUsage.IsEmpty(),
                @$"
Documentation: {DocumentationDomain}#RJIT_CR_API_C_00029

Method implementation should only have Mediator call: {Environment.NewLine}{moreAsMediatorUsage.Select(error => error.Error).Flatten(Environment.NewLine)}{Environment.NewLine}");
        }
    }
